1171	// A rejected re-wire (unknown upstream, or an upstream that would close a
1172	// cycle through the dataset's own downstream) must name the offending upstream
1173	// and leave every previously queryable relationship exactly as it was.
1174	func TestFailedRewireLeavesImpactsUntouched(t *testing.T) {
1175		graph := map[string]*Lineage{}
1176		mustRegister(t, graph, "raw")
1177		mustRegister(t, graph, "mid", "raw")
1178		mustRegister(t, graph, "leaf", "mid")
1179		mustRegister(t, graph, "newsrc")
1180		mustRegister(t, graph, "newleaf", "newsrc")
1181	
