1193		err = Register(graph, Dataset{Name: "mid"}, []string{"leaf"})
1194		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "leaf") {
1195			t.Fatalf("want cycle error naming leaf, got %v", err)
1196		}
1197	
1198		if !reflect.DeepEqual(snapshot(graph), before) {
1199			t.Fatalf("rejected re-wires changed graph: before=%v after=%v", before, snapshot(graph))
1200		}
1201		if got := mustImpacts(t, graph, "raw"); !reflect.DeepEqual(got, rawBefore) {
1202			t.Fatalf("raw impacts changed after rejected re-wires: got %v, want %v", got, rawBefore)
1203		}
1204		if got := mustImpacts(t, graph, "newsrc"); !reflect.DeepEqual(got, newBefore) {
1205			t.Fatalf("newsrc impacts changed after rejected re-wires: got %v, want %v", got, newBefore)
1206		}
1207		assertImpact(t, rawBefore, "mid", 1, []string{"raw", "mid"})
1208		assertImpact(t, rawBefore, "leaf", 2, []string{"raw", "mid", "leaf"})
