1212	type snap struct {
1213		parents  map[string][]string
1214		children map[string][]string
1215	}
1216	
1217	func snapshot(graph map[string]*Lineage) snap {
1218		s := snap{map[string][]string{}, map[string][]string{}}
1219		for name, e := range graph {
1220			s.parents[name] = append([]string(nil), e.Parents...)
1221			s.children[name] = append([]string(nil), e.Children...)
1222		}
1223		return s
1224	}
